[TFMPageType('Registrations', "Registrations")]
class TFMPageRegistrationsConfiguration extends TFMPageConfiguration
{
    boolean     deleteRegistrationEnabled;
    boolean     deleteAllRegistrationsEnabled;
    TFMPageTitleString				deleteRegistrationTitle;
    TFMPageTitleString				deleteAllRegistrationsTitle;
    TFMListId	listId;

    boolean openEnabled;
    boolean refreshEnabled;

}

Method.Source:
[TFMPageConfigurationAttributeAttribute(true,'list/open','enabled'), TFMPageAction]
public boolean parmOpenEnabled(boolean _openEnabled = openEnabled)
{
    openEnabled = _openEnabled;
    return openEnabled;
}

[TFMPageConfigurationAttributeAttribute(true,'list/refresh','enabled', true,true,false,true), TFMPageAction]
public boolean parmRefreshEnabled(boolean _refreshEnabled = refreshEnabled)
{
    refreshEnabled = _refreshEnabled;
    return refreshEnabled;
}

[TFMPageConfigurationAttributeAttribute(classStr(TFMListRegistrations),'list','',true)]
public TFMListId parmListId(TFMListId _listId = listId)
{
    TFMList			listCls;
    listId = _listId;
    if (className2Id(listId))
    {
        listCls = new SysDictClass(className2Id(listId)).makeObject();
        listId = listCls.parmListName();
    }
    return listId;
}

[TFMPageConfigurationAttributeAttribute('DeleteRegistration','deleteRegistration','title',true,true,false,true),TFMPageAction]
public TFMPageTitleString parmDeleteRegistrationTitle(TFMPageTitleString _viewRegistrationTitle = deleteRegistrationTitle)
{
    deleteRegistrationTitle = _viewRegistrationTitle;
    return deleteRegistrationTitle;
}

[TFMPageConfigurationAttributeAttribute(true,'deleteRegistration','enabled',true,true,false,true),TFMPageAction]
public boolean parmDeleteRegistrationEnabled(boolean _viewRegistrationsEnabled = deleteRegistrationEnabled)
{
    deleteRegistrationEnabled = _viewRegistrationsEnabled;
    return deleteRegistrationEnabled;
}

[TFMPageConfigurationAttributeAttribute('DeleteAllRegistrations','deleteAllRegistrations','title',true,true,false,true),TFMPageAction]
public TFMPageTitleString parmDeleteAllRegistrationsTitle(TFMPageTitleString _viewAllRegistrationsTitle = deleteAllRegistrationsTitle)
{
    deleteAllRegistrationsTitle = _viewAllRegistrationsTitle;
    return deleteAllRegistrationsTitle;
}

[TFMPageConfigurationAttributeAttribute(true,'deleteAllRegistrations','enabled',true,true,false,true),TFMPageAction]
public boolean parmDeleteAllRegistrationsEnabled(boolean _viewAllRegistrationsEnabled = deleteAllRegistrationsEnabled)
{
    deleteAllRegistrationsEnabled = _viewAllRegistrationsEnabled;
    return deleteAllRegistrationsEnabled;
}
